CREATE TABLE IF NOT EXISTS ldl_score_core_octopus.t_dim_logistics_agreement_status_2 (
logistics_agmt_status_cd STRING(20) NOT NULL OPTIONS(description='Status_2 of an agreement'),
logistics_agmt_status_descr STRING(100)
OPTIONS(description='Values are:Created(Erstellt) - The contract status_2 created indicates that a contract was created for the first time.Processed(Bearbeitet) - The contract status_2 processed means that a change has been made to a contract and the processing has been completed.  employee_2 (not the person who created the contract) -  from the internal organizational unit_2 (contract management) - .Approved(Freigegeben) - The contract status_2 released indicates that a contract has been released by freight purchasing as an internal organizational unit_2 (foundation) - .Sent(Versendet) - The contract status_2 sent denotes the status_2 that a contract has been sent to the logistics service provider (if by post) -  or to freight purchasing (internal organizational unit_2) -  and logistics service provider (via Adobe Sign) - .signed(Unterschrieben) - The contract status_2 signed indicates that a contract has been signed by both contracting parties.'),
logistics_agmt_status_descr_de STRING(100)
OPTIONS(description='German description of statuses:Created(Erstellt) - The contract status_2 created indicates that a contract was created for the first time.Processed(Bearbeitet) - The contract status_2 processed means that a change has been made to a contract and the processing has been completed.  employee_2 (not the person who created the contract) -  from the internal organizational unit_2 (contract management) - .Approved(Freigegeben) - The contract status_2 released indicates that a contract has been released by freight purchasing as an internal organizational unit_2 (foundation) - .Sent(Versendet) - The contract status_2 sent denotes the status_2 that a contract has been sent to the logistics service provider (if by post) -  or to freight purchasing (internal organizational unit_2) -  and logistics service provider (via Adobe Sign) - .signed(Unterschrieben) - The contract status_2 signed indicates that a contract has been signed by both contracting parties.'),
logistics_agmt_status_descr_en STRING(100)
OPTIONS(description='English description of statuses:	Created(Erstellt) - The contract status_2 created indicates that a contract was created for the first time.Processed(Bearbeitet) - The contract status_2 processed means that a change has been made to a contract and the processing has been completed.  employee_2 (not the person who created the contract) -  from the internal organizational unit_2 (contract management) - .Approved(Freigegeben) - The contract status_2 released indicates that a contract has been released by freight purchasing as an internal organizational unit_2 (foundation) - .Sent(Versendet) - The contract status_2 sent denotes the status_2 that a contract has been sent to the logistics service provider (if by post) -  or to freight purchasing (internal organizational unit_2) -  and logistics service provider (via Adobe Sign) - .signed(Unterschrieben) - The contract status_2 signed indicates that a contract has been signed by both contracting parties.'),
dwh_created_tmsp TIMESTAMP NOT NULL
OPTIONS(description='The point in time when this record was created in the data warehouse.'),
dwh_updated_tmsp TIMESTAMP NOT NULL
OPTIONS(description='The point in time when this record was created or last updated.'),
PRIMARY KEY (logistics_agmt_status_cd) NOT ENFORCED
)
OPTIONS(description='Agreement status_2 describes the current work status_2/status_2 of the contract. A distinction is made between different forms.');